package app.jmbatch.android;

import android.app.*;
import android.graphics.Color;
import android.content.res.ColorStateList;
import android.view.*;
import android.widget.*;
import android.text.*;
import java.util.function.Supplier;

/** The four sections and horizontal controls of settings concept C001. */
final class SettingsScreen {
    private final Activity a;private final Store store;private final GithubUpdates updates;private final Runnable choose,save;private final Supplier<TextView> output;
    private final int rail,space,font;
    private Runnable persist=()->{};
    SettingsScreen(Activity a,Store store,GithubUpdates updates,Runnable choose,Supplier<TextView> output,Runnable save){this.a=a;this.store=store;this.updates=updates;this.choose=choose;this.output=output;this.save=save;int width=(int)(a.getResources().getDisplayMetrics().widthPixels/a.getResources().getDisplayMetrics().density);int backWidth=(int)Math.ceil(28*a.getResources().getConfiguration().fontScale*2.25f)+16;rail=Math.max(backWidth,Math.min(166,width/4));space=width<500?10:24;font=width<500?11:14;}
    View build(Runnable back){
        LinearLayout root=new LinearLayout(a);root.setBackgroundColor(Color.WHITE);LinearLayout nav=Ui.column(a),body=Ui.column(a);nav.setPadding(Ui.dp(a,8),Ui.dp(a,20),Ui.dp(a,8),0);nav.setBackgroundColor(0xffedf0f5);body.setPadding(Ui.dp(a,space),Ui.dp(a,20),Ui.dp(a,space),Ui.dp(a,24));
        root.addView(nav,new LinearLayout.LayoutParams(Ui.dp(a,rail),-1));ScrollView scroll=new ScrollView(a);scroll.setVerticalScrollBarEnabled(false);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(0,-1,1));Button returnButton=Ui.button(a,"←",back);returnButton.setContentDescription("返回");returnButton.setTextSize(28);Ui.smallIconGlyph(returnButton);nav.addView(returnButton,new LinearLayout.LayoutParams(-2,-2));Ui.gap(nav,16);TextView settings=Ui.heading(a,"设置");settings.setPadding(Ui.dp(a,8),0,0,Ui.dp(a,20));nav.addView(settings);
        String[] titles={"下载","阅读","更新","软件说明"};View[] anchors=new View[4];TextView[] links=new TextView[4];
        for(int i=0;i<4;i++){final int index=i;links[i]=Ui.text(a,titles[i],font);links[i].setPadding(Ui.dp(a,8),Ui.dp(a,14),0,Ui.dp(a,14));links[i].setOnClickListener(v->scroll.smoothScrollTo(0,anchors[index].getTop()));nav.addView(links[i]);Ui.gap(nav,4);}
        anchors[0]=section(body,"下载",false);EditText timeout=number(body,"任务超时时间",store.settings.timeout),concurrent=number(body,"同时下载任务数",store.settings.concurrentTasks),limit=number(body,"下载限速",store.settings.downloadLimitKB);
        LinearLayout allRow=row();TextView allLabel=label("默认下载全部章节");allRow.addView(allLabel,new LinearLayout.LayoutParams(0,-2,2));CheckBox all=new CheckBox(a);all.setButtonTintList(ColorStateList.valueOf(Ui.MUTED));all.setChecked(store.settings.downloadAllChapters);allRow.addView(all,new LinearLayout.LayoutParams(0,Ui.dp(a,42),3));body.addView(allRow);Ui.gap(body,8);
        LinearLayout pathRow=row();pathRow.addView(label("保存目录"),new LinearLayout.LayoutParams(0,-2,1));TextView path=output.get();if(path.getParent()!=null)((ViewGroup)path.getParent()).removeView(path);path.setText(OutputDirectory.display(a,store.settings.outputUri));path.setTextColor(Ui.MUTED);path.setTextSize(font);path.setSingleLine(false);path.setMaxLines(Integer.MAX_VALUE);path.setEllipsize(null);path.setHorizontallyScrolling(false);path.setTextIsSelectable(true);path.setBackground(Ui.shape(a,Ui.BG,6,true));path.setPadding(Ui.dp(a,8),0,Ui.dp(a,8),0);Ui.compact(path);pathRow.addView(path,new LinearLayout.LayoutParams(0,-2,2));Button directory=button("选择目录",choose);LinearLayout.LayoutParams pick=new LinearLayout.LayoutParams(-2,-2);pick.leftMargin=Ui.dp(a,6);pathRow.addView(directory,pick);body.addView(pathRow);
        LinearLayout clear=row();View indent=new View(a);clear.addView(indent,new LinearLayout.LayoutParams(0,1,1.4f));LinearLayout right=row();right.addView(button("清除缓存",()->CleanupScreen.show(a,store,null)));clear.addView(right,new LinearLayout.LayoutParams(0,-2,3.6f));LinearLayout.LayoutParams clearSpace=new LinearLayout.LayoutParams(-1,-2);clearSpace.topMargin=Ui.dp(a,8);body.addView(clear,clearSpace);Ui.gap(body,6);
        anchors[1]=section(body,"阅读",true);body.addView(label("阅读模式"));RadioGroup modes=choices(body,new String[]{"左右翻页","上下翻页","上下滚动"},store.settings.readingMode.equals("paged")?0:store.settings.readingMode.equals("vertical")?1:2);final boolean[] modeChanged={false};Ui.gap(body,12);body.addView(label("多章节观看模式"));RadioGroup chapters=choices(body,new String[]{"多章节合一","分章节观看"},store.settings.chapterViewMode-1);
        anchors[2]=section(body,"更新",true);LinearLayout update=(LinearLayout)anchors[2];TextView title=(TextView)update.getChildAt(0);title.setLayoutParams(new LinearLayout.LayoutParams(Ui.dp(a,rail>100?100:44),-2));Button updateButton=button("检查更新",updates::manualCheck);update.addView(updateButton);updates.bindSettingsButton(updateButton);View gap=new View(a);update.addView(gap,new LinearLayout.LayoutParams(Ui.dp(a,8),1));update.addView(button("更新日志",updates::showNotes));
        anchors[3]=section(body,"软件说明",true);body.addView(label("本软件主要为作者自用，维护与开发均由 AI 进行"));body.addView(label("详情请见："));TextView repo=label("github.com/norskhelo/jmbatch");repo.setTextColor(Ui.BLUE);repo.setOnClickListener(v->a.startActivity(new android.content.Intent(android.content.Intent.ACTION_VIEW,android.net.Uri.parse("https://github.com/norskhelo/jmbatch"))));body.addView(repo);
        persist=()->{try{Store.Settings options=new Store.Settings(store.settings.json());options.timeout=integer(timeout);options.concurrentTasks=integer(concurrent);options.downloadLimitKB=integer(limit);options.downloadAllChapters=all.isChecked();options.chapterViewMode=selected(chapters)+1;if(modeChanged[0])options.readingMode=new String[]{"paged","vertical","scroll"}[selected(modes)];options.validate();store.settings=options;save.run();}catch(Exception ignored){/* Incomplete edits keep the last valid settings. */}};
        for(EditText field:new EditText[]{timeout,concurrent,limit})field.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){persist.run();}public void afterTextChanged(Editable e){}});
        all.setOnCheckedChangeListener((b,on)->persist.run());chapters.setOnCheckedChangeListener((g,id)->persist.run());modes.setOnCheckedChangeListener((g,id)->{modeChanged[0]=true;persist.run();});
        Runnable highlight=()->{int index=0;for(int i=0;i<4;i++)if(anchors[i].getTop()<=scroll.getScrollY()+Ui.dp(a,28))index=i;if(body.getHeight()>scroll.getHeight()+Ui.dp(a,8)&&body.getHeight()-scroll.getHeight()-scroll.getScrollY()<Ui.dp(a,8))index=3;for(int i=0;i<4;i++){links[i].setTextColor(i==index?Ui.BLUE:Ui.INK);links[i].setBackground(Ui.shape(a,i==index?0xffd1d5df:0xffedf0f5,6,false));}};
        scroll.setOnScrollChangeListener((v,x,y,ox,oy)->highlight.run());scroll.post(highlight);return root;
    }
    void save(){persist.run();}
    private TextView label(String text){return Ui.text(a,text,font);}
    private LinearLayout row(){LinearLayout row=new LinearLayout(a);row.setGravity(Gravity.CENTER_VERTICAL);return row;}
    private Button button(String title,Runnable action){Button b=Ui.button(a,title,action);b.setTextSize(font+2);return b;}
    private View section(LinearLayout body,String title,boolean line){if(line){Ui.gap(body,20);View divider=new View(a);divider.setBackgroundColor(Ui.LINE);body.addView(divider,new LinearLayout.LayoutParams(-1,Ui.dp(a,1)));Ui.gap(body,14);}LinearLayout row=row();TextView heading=Ui.heading(a,title);heading.setTextSize(font+6);row.addView(heading);body.addView(row);return row;}
    private EditText number(LinearLayout body,String title,int value){LinearLayout row=row();row.addView(label(title),new LinearLayout.LayoutParams(0,-2,2));EditText input=Ui.input(a,"",true);input.setTextSize(font);input.setPadding(Ui.dp(a,12),0,Ui.dp(a,8),0);input.setText(Integer.toString(value));row.addView(input,new LinearLayout.LayoutParams(0,-2,3));body.addView(row);Ui.gap(body,8);return input;}
    private int integer(EditText input){return Integer.parseInt(input.getText().toString().trim());}
    private RadioGroup choices(LinearLayout parent,String[] names,int chosen){RadioGroup group=new RadioGroup(a);group.setOrientation(RadioGroup.HORIZONTAL);for(int i=0;i<names.length;i++){RadioButton b=new RadioButton(a);b.setId(View.generateViewId());b.setText(names[i]);b.setTextSize(font);b.setTextColor(Ui.INK);b.setPadding(0,0,0,0);b.setButtonTintList(ColorStateList.valueOf(Ui.MUTED));group.addView(b,new RadioGroup.LayoutParams(0,Ui.dp(a,42),1));if(i==chosen)group.check(b.getId());}parent.addView(group);return group;}
    private int selected(RadioGroup group){return group.indexOfChild(group.findViewById(group.getCheckedRadioButtonId()));}
}
